/* Generated by build-sw.mjs. Only public, build-listed shell files enter Cache Storage. */
const BUILD = __BUILD__;
const CACHE = `daylight-shell-${BUILD}`;
const FILES = __FILES__;
const owned = (name) =>
  name.startsWith("daylight-shell-") || /^daylight-[a-f0-9]{16}$/.test(name);
const windows = async () =>
  (
    await self.clients.matchAll({ type: "window", includeUncontrolled: true })
  ).filter((client) => client.url.startsWith(self.registration.scope));

self.addEventListener("install", (event) => {
  // A failed/incomplete download must not replace the working offline shell.
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      try {
        for (const file of FILES) {
          const response = await fetch(new Request(file, { cache: "reload" }));
          if (!response.ok || response.redirected)
            throw new Error("Shell download failed");
          if (
            file === "/index.html" &&
            !(await response.clone().text()).includes(
              `name="daylight-build" content="${BUILD}"`,
            )
          )
            throw new Error("Deployment changed during download");
          if (
            /\.js$/.test(file) &&
            !/(javascript|ecmascript)/i.test(
              response.headers.get("content-type") || "",
            )
          )
            throw new Error("Expected JavaScript");
          if (
            /\.css$/.test(file) &&
            !/text\/css/i.test(response.headers.get("content-type") || "")
          )
            throw new Error("Expected CSS");
          await cache.put(file, response);
        }
      } catch (error) {
        await caches.delete(CACHE);
        throw error;
      }
    })(),
  );
});

async function cleanup() {
  const clients = await windows();
  const versions = await Promise.all(
    clients.map(
      (client) =>
        new Promise((resolve) => {
          const channel = new MessageChannel();
          const timer = setTimeout(() => {
            channel.port1.close();
            resolve(null);
          }, 1500);
          channel.port1.onmessage = (event) => {
            clearTimeout(timer);
            channel.port1.close();
            resolve(
              typeof event.data?.buildId === "string"
                ? event.data.buildId
                : null,
            );
          };
          client.postMessage({ type: "DAYLIGHT_BUILD" }, [channel.port2]);
        }),
    ),
  );
  // Suspended/legacy clients cannot confirm their version: retain their assets.
  if (versions.includes(null)) return;
  const keep = new Set([
    CACHE,
    ...versions.map((id) => `daylight-shell-${id}`),
  ]);
  await Promise.all(
    (await caches.keys())
      .filter((name) => owned(name) && !keep.has(name))
      .map((name) => caches.delete(name)),
  );
}
self.addEventListener("activate", (event) =>
  event.waitUntil(
    (async () => {
      await self.clients.claim();
      await cleanup();
    })(),
  ),
);
self.addEventListener("message", (event) => {
  const reply = (data) => event.ports[0]?.postMessage(data);
  if (event.data?.type === "DAYLIGHT_VERSION") reply({ buildId: BUILD });
  if (event.data?.type === "DAYLIGHT_CLEANUP") event.waitUntil(cleanup());
  if (event.data?.type === "DAYLIGHT_ACTIVATE")
    event.waitUntil(
      (async () => {
        const clients = await windows();
        // Include uncontrolled and suspended windows. Never infer that silence means safe.
        if (clients.length !== 1 || clients[0].id !== event.source?.id) {
          reply({ blocked: "tabs" });
          return;
        }
        reply({ activating: true });
        await self.skipWaiting();
      })(),
    );
});
self.addEventListener("fetch", (event) => {
  const request = event.request;
  const url = new URL(request.url);
  if (request.method !== "GET" || url.origin !== self.location.origin) return;
  if (request.mode === "navigate") {
    event.respondWith(
      (async () => {
        const cache = await caches.open(CACHE);
        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), 5000);
        try {
          const response = await fetch(
            new Request(request, {
              cache: "no-store",
              signal: controller.signal,
            }),
          );
          if (
            !response.ok ||
            !/text\/html/i.test(response.headers.get("content-type") || "")
          )
            throw new Error("Navigation failed");
          const html = await response.clone().text();
          if (html.includes(`name="daylight-build" content="${BUILD}"`))
            return response;
          // Keep HTML/JS/CSS on the same build until the new complete shell can activate.
          const client = await self.clients.get(
            event.resultingClientId || event.clientId,
          );
          client?.postMessage({ type: "DAYLIGHT_DEPLOYED" });
        } catch {
          /* Network failure/timeout: the complete installed shell is available. */
        } finally {
          clearTimeout(timer);
        }
        return (await cache.match("/index.html")) || Response.error();
      })(),
    );
    return;
  }
  // Do not intercept version checks, auth callbacks, APIs, or arbitrary same-origin URLs.
  if (
    FILES.includes(url.pathname) ||
    /^\/assets\/[^/]+\.(js|css)$/.test(url.pathname)
  ) {
    event.respondWith(
      (async () => {
        const current = await caches.open(CACHE);
        const cached = await current.match(url.pathname);
        if (cached) return cached;
        // An older open page may still need its immutable chunks after activation.
        if (url.pathname.startsWith("/assets/")) {
          for (const key of (await caches.keys()).filter(owned)) {
            const old = await (await caches.open(key)).match(url.pathname);
            if (old) return old;
          }
        }
        return fetch(request);
      })(),
    );
  }
});
